	/** Iterates over the set bits of a bit array. */
	class FSetBitIterator : public FRelativeBitReference
	{
	public:
		explicit FSetBitIterator(const TBitArray<>& InArray, int32 StartIndex = 0)
			: FRelativeBitReference(StartIndex)
			, Array(InArray)
			, UnvisitedBitMask((~0u) << (StartIndex & (NumBitsPerDWORD - 1)))
			, CurrentBitIndex(StartIndex)
			, BaseBitIndex(StartIndex & ~(NumBitsPerDWORD - 1))
		{
			if (StartIndex != Array.Num())
			{
				FindFirstSetBit();
			}
		}

		inline FSetBitIterator& operator++()
		{
			// Mark the current bit as visited.
			UnvisitedBitMask &= ~this->Mask;

			// Find the first set bit that hasn't been visited yet.
			FindFirstSetBit();

			return *this;
		}

		inline explicit operator bool() const { return CurrentBitIndex < Array.Num(); }

		inline bool operator==(const FSetBitIterator& Rhs) const { return CurrentBitIndex == Rhs.CurrentBitIndex && &Array == &Rhs.Array; }
		inline bool operator!=(const FSetBitIterator& Rhs) const { return !(*this == Rhs); }

		inline int32 GetIndex() const { return CurrentBitIndex; }

		void FindFirstSetBit()
		{
			const uint32* ArrayData     = Array.GetData();
			const int32   ArrayNum      = Array.Num();
			const int32   LastWordIndex = (ArrayNum - 1) / NumBitsPerDWORD;

			// Advance to the next non-zero uint32.
			uint32 RemainingBitMask = ArrayData[this->WordIndex] & UnvisitedBitMask;
			while (!RemainingBitMask)
			{
				++this->WordIndex;
				BaseBitIndex += NumBitsPerDWORD;
				if (this->WordIndex > LastWordIndex)
				{
					// We've advanced past the end of the array.
					CurrentBitIndex = ArrayNum;
					return;
				}

				RemainingBitMask = ArrayData[this->WordIndex];
				UnvisitedBitMask = ~0u;
			}

			// This operation has the effect of unsetting the lowest set bit of BitMask
			const uint32 NewRemainingBitMask = RemainingBitMask & (RemainingBitMask - 1);

			// This operation XORs the above mask with the original mask, which has the effect
			// of returning only the bits which differ; specifically, the lowest bit
			this->Mask = NewRemainingBitMask ^ RemainingBitMask;

			// If the Nth bit was the lowest set bit of BitMask, then this gives us N
			CurrentBitIndex = BaseBitIndex + NumBitsPerDWORD - 1 - FMath::CountLeadingZeros(this->Mask);

			// If we've accidentally iterated off the end of an array but still within the same DWORD
			// then set the index to the last index of the array
			if (CurrentBitIndex > ArrayNum)
			{
				CurrentBitIndex = ArrayNum;
			}
		}

	private:
		const TBitArray<>& Array;

		uint32 UnvisitedBitMask;
		int32  CurrentBitIndex;
		int32  BaseBitIndex;
	};

	inline FSetBitIterator begin(const TBitArray<>& Array) { return FSetBitIterator(Array, 0); }
	inline FSetBitIterator end  (const TBitArray<>& Array) { return FSetBitIterator(Array, Array.Num()); }

	/*
	* A bit array is inline storage, a pointer and two ints. Relocating one copies the inline bytes
	* along with the rest, and the allocator recomputes its pointer from the new address.
	*/
	template <typename Allocator>
	struct TIsTriviallyRelocatable<TBitArray<Allocator>>
	{
		static constexpr bool Value = true;
	};


